package net.civeira.phylax.features.notification.smtpoutboundconfig.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class RateLimitVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property rate limit of smtp outbound config ")
  void test_rate_limit_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> RateLimitVO.tryFrom(null));
    Assertions.assertEquals(1, RateLimitVO.from(1).getRateLimit());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> RateLimitVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + 1 + "]", RateLimitVO.from(1).toString());
  }
}
